://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=105&code=111110&q=1&s=0406&t=Q","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"111110","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-111-2-17","law":"","qno":"17","year":"111","major":"研究邏輯","opt_a":"社會福利機構","opt_b":"薪資所得","opt_c":"社會工作師","opt_d":"全國各縣市","round":"第二次","topic":"研究設計 > 分析單位辨識","answer":"C","exp_raw":"","exp_why":"承上題,研究「全國社工師的薪資」——分析單位是社會工作師(每位社工師);(C)。","mistake":"概念混淆","subject":"社會工作研究方法","exp_trap":"分析單位=「結論所描述的對象」;本題是個別社工師。","keywords":"分析單位, 社會工作師, 個人, 薪資所得, 機構","mnemonic":"分析單位=社會工作師(研究其薪資)。","question":"承上題，該研究之分析單位為何？","extension":"研究設計;分析單位。","exp_others":"(A)社會福利機構、(B)薪資所得是「變項」、(D)全國各縣市——皆非本題的分析對象。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=105&code=111110&q=1&s=0406&t=Q","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"111110","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-111-2-18","law":"","qno":"18","year":"111","major":"統計檢定","opt_a":"多元迴歸分析","opt_b":"內容分析","opt_c":"因素分析","opt_d":"卡方檢定","round":"第二次","topic":"迴歸分析 > 多元迴歸應用","answer":"A","exp_raw":"","exp_why":"(A)多元迴歸分析：以多個自變項共同預測連續依變項——承上題的設計用多元迴歸。","mistake":"概念混淆","subject":"社會工作研究方法","exp_trap":"統計方法選擇口訣:依變項連續+自變項2組→t檢定(同一批人前後測=相依/配對t;不同兩組=獨立t,先做變異數同質性檢定);自變項3組以上→變異數分析ANOVA(兩組時F=t平方,等價);兩個連續變項關聯→積差相關;兩個類別變項→卡方;多自變項預測連續依變項(含控制變項)→(多元)迴歸;依變項是類別→不可用迴歸(用判別/邏輯斯);縮題建構面→因素分析(探索性EFA建立構面;驗證性CFA檢驗既有結構)。","keywords":"多元迴歸, 薪資所得, 相關因素, 卡方檢定, 因素分析","mnemonic":"統計選擇:依變項連續+2組→t檢定(配對/獨立);3組以上→ANOVA;兩連續變項關聯→積差相關;兩類別變項→卡方。","question":"承上題，此一研究可能使用下列何種統計分析方法？","extension":"迴歸分析(多元迴歸)。","exp_others":"(B)內容分析是文本研究、(C)因素分析縮構面、(D)卡方是類別。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=105&code=111110&q=1&s=0406&t=Q","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"111110","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-111-2-29","law":"","qno":"29","year":"111","major":"研究邏輯","opt_a":"4 家平面媒體","opt_b":"移工","opt_c":"1992 年至 2018 年的每一年","opt_d":"每一則對移工的相關報導","round":"第二次","topic":"研究設計 > 內容分析分析單位","answer":"D","exp_raw":"","exp_why":"承上題,研究分析的是「每一則對移工的相關報導」——分析單位是每一則報導;(D)。","mistake":"概念混淆","subject":"社會工作研究方法","exp_trap":"內容分析的分析單位常是「每一則文本(報導)」。","keywords":"分析單位, 新聞報導, 媒體, 內容分析, 樣本單位","mnemonic":"分析單位=每一則報導(內容分析)。","question":"承上題，此研究的分析單位為何？","extension":"研究設計;分析單位。","exp_others":"(A)4家平面媒體、(B)移工、(C)每一年——皆非「被登錄分析」的單位。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=105&code=111110&q=1&s=0406&t=Q","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"111110","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-111-2-30","law":"","qno":"30","year":"111","major":"內容分析","opt_a":"歷史比較分析法","opt_b":"內容分析法","opt_c":"次級資料分析法","opt_d":"調查研究法","round":"第二次","topic":"內容分析法 > 內容分析法辨識","answer":"B","exp_raw":"","exp_why":"對大量報導文本做系統登錄分析——這是內容分析法;(B)。","mistake":"概念混淆","subject":"社會工作研究方法","exp_trap":"內容分析=把「文本(報導)」依類目系統登錄、量化分析。","keywords":"內容分析法, 新聞報導, 媒體形象, 系統分析, 次級資料","mnemonic":"內容分析法=系統登錄分析報導文本。","question":"承上題，這個研究所採用的研究方法為何？","extension":"內容分析法;辨識。","exp_others":"(A)歷史比較分析偏跨時空比較詮釋、(C)次級資料分析用既有「數據」、(D)調查研究用問卷——皆不符「登錄文本內容」。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=105&code=111110&q=1&s=0406&t=Q","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"111110","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-105-2-07","law":"","qno":"7","year":"105","major":"統計檢定","opt_a":"在不增加 的情況下，我們可以增加樣本數達到降低 的目的","opt_b":"1-稱為檢定力，對立假設為真時，錯誤判斷的機率","opt_c":"是指虛無假設為假，不拒絕虛無假設的機率","opt_d":"是指虛無假設為真，但拒斥虛無假設的機率","round":"第二次","topic":"統計檢定 > 型 I/II 錯誤","answer":"B","exp_raw":"","exp_why":"用煙霧警報器想：型Ⅰ錯誤＝沒火卻響（誤報）；型Ⅱ錯誤＝有火卻沒響（漏掉）。「檢定力」就是「真的失火時，警報抓得到的本事」——它是抓對的能力、不是出錯的機率，越高越好。(B)把檢定力說成「錯誤判斷的機率」，剛好說反了。","mistake":"概念混淆","subject":"社會工作研究方法","exp_trap":"檢定力是「好能力」，常被偷換成「錯誤率」。記住1−β＝抓到真效果的本事。","keywords":"型I錯誤, 型II錯誤, 檢定力","mnemonic":"型Ⅰ＝誤報、型Ⅱ＝漏報；檢定力＝真失火時警報抓得到的本事，越大越靈，不是出錯率。","question":"型Ⅰ錯誤稱為 ，型Ⅱ錯誤稱為 ，下列敘述何者錯誤？","extension":"檢定力四要素（α、效果量、樣本數、變異）→增樣本提升檢定力。","exp_others":"(A)不動α而加大樣本可降低β，正確；(C)β＝有火沒響（虛無為假卻不拒絕）的機率，正確；(D)α＝沒火卻響（虛無為真卻拒絕）的機率，正確。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=107&code=105090&q=1&s=0606&t=Q","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"105090","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"DS-106-1-34","law":"","qno":"34","year":"106","major":"會談與溝通技巧","opt_a":"深層次的同理心，將覺察到的個案情緒反應出來 心，將覺察到的個案情緒反應出來","opt_b":"示範真誠的行為或適時揭露自己的經驗、想法","opt_c":"透過案主的轉移，處理其和工作者的關係之議題 其和工作者的關係之議題","opt_d":"同理心或設身處地和案主互動，並給予的正向回饋 心或設身處地和案主互動，並給予的正向回饋","round":"第一次","topic":"自我揭露 > 使用自我","answer":"B","exp_raw":"","exp_why":"(B)使用自我(use of self)：示範真誠的行為、或適時揭露自己的經驗與想法。","mistake":"概念混淆","subject":"社會工作直接服務","exp_trap":"自我表露/使用自我:有意有目的透露自身訊息(口語與非口語);類型＝立即性與個人性;以誠實為基礎且須考量是否有助專業關係與案主利益;含分享與面質意味。","keywords":"使用自我, use of self, 示範真誠, 揭露經驗, 技術","mnemonic":"使用自我/自我表露＝有目的透露自身訊息(口語非口語);類型＝立即性與個人性;以誠實為基礎、須利於專業關係與案主利益。","question":"使用自我（use of self）是社會工作直接服務常用的技術，請問下列那一項屬於使用自我 的做法？","extension":"會談技巧(使用自我)。","exp_others":"(A)是深層同理、(C)是處理轉移、(D)是同理與正向回饋——皆非『使用自我』的核心定義。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=107&code=106030&q=1&s=0602&t=Q","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"106030","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null}]$pre$::jsonb;
