 itm jsonb; actual jsonb;other_old jsonb;other_new jsonb;
 grading_old jsonb;grading_new jsonb;config_old jsonb;config_new jsonb;changed integer;
BEGIN
 IF (SELECT count(*) FROM public.questions)<>4800 THEN RAISE EXCEPTION 'P0 corpus count mismatch';END IF;
 SELECT jsonb_agg(to_jsonb(q) ORDER BY id) INTO other_old FROM public.questions q WHERE id NOT IN ('DS-108-2-23','R-114-1-17','R-111-2-14','R-111-2-15','R-111-2-17','R-111-2-18','R-111-2-29','R-111-2-30','R-105-2-07','DS-106-1-34');
 SELECT jsonb_agg(jsonb_build_array(id,answer,accepted_answers,grading_mode) ORDER BY id) INTO grading_old FROM public.questions;
 SELECT to_jsonb(c) INTO config_old FROM public.ai_analysis_job_config c WHERE id=true;
 IF config_old->>'enabled'<>'false' THEN RAISE EXCEPTION 'P0 AI config enabled';END IF;
 FOR itm IN SELECT value FROM jsonb_array_elements(old_rows) LOOP
   SELECT to_jsonb(q) INTO STRICT actual FROM public.questions q WHERE id=itm->>'id' FOR UPDATE;
   IF actual IS DISTINCT FROM itm THEN RAISE EXCEPTION 'P0 before image differs %',itm->>'id';END IF;
 END LOOP;
  UPDATE public.questions SET question='使用自我（use of self）是社會工作直接服務常用的技術，請問下列那一項屬於使用自我的做法？', opt_a='深層次的同理心，將覺察到的個案情緒反應出來', opt_c='透過案主的轉移，處理其和工作者的關係之議題', opt_d='同理心或設身處地和案主互動，並給予的正向回饋' WHERE id='DS-106-1-34';
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'SWSI ten source row count mismatch'; END IF;
  UPDATE public.questions SET question='有關團體工作開始階段的工作重點和工作目標，下列何者正確？①建立團體規範 ②加強正向動機，降低抗拒 ③處理團體成員參與的問題 ④處理成員之間的衝突與緊張 ⑤創造安全與信任關係 ⑥發展溝通、地位、角色與規範的彈性結構 ⑦協助成員感覺自己是團體的一份子 ⑧穩定成員的參與及團體的運作', opt_a='②④⑥⑧' WHERE id='DS-108-2-23';
