 GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>10 THEN RAISE EXCEPTION 'P0 stale analysis quarantine failed';END IF;
 FOR itm IN SELECT value FROM jsonb_array_elements(new_rows) LOOP
   SELECT to_jsonb(q) INTO STRICT actual FROM public.questions q WHERE id=itm->>'id';
   IF actual IS DISTINCT FROM itm THEN RAISE EXCEPTION 'P0 after image differs %',itm->>'id';END IF;
 END LOOP;
 SELECT jsonb_agg(to_jsonb(q) ORDER BY id) INTO other_new FROM public.questions q WHERE id NOT IN ('DS-108-2-23','R-114-1-17','R-111-2-14','R-111-2-15','R-111-2-17','R-111-2-18','R-111-2-29','R-111-2-30','R-105-2-07','DS-106-1-34');
